create table if not exists public.agent_b_handoffs(handoff_id uuid primary key,discovery_id uuid not null references public.agent_b_discoveries(discovery_id) on delete restrict,version integer not null, status text not null check(status in ('ISSUED','SUPERSEDED')),source_runtime_version bigint not null,decision jsonb not null,previous_handoff_id uuid null references public.agent_b_handoffs(handoff_id) on delete restrict,issued_at timestamptz not null,unique(discovery_id,version));
alter table public.agent_b_handoffs enable row level security; revoke all on table public.agent_b_handoffs from public,anon,authenticated,service_role; grant select on public.agent_b_handoffs to authenticated;
create policy agent_b_handoff_owner_read on public.agent_b_handoffs for select to authenticated using(exists(select 1 from public.agent_b_discoveries d join public.agent_b_discovery_access a using(discovery_id) where d.discovery_id=agent_b_handoffs.discovery_id and d.owner_id=auth.uid() and a.identity_id=auth.uid() and a.role='OWNER'));
